), by_words as (
  select distinct on (w.id) w.id as wine_id, w.appellation_id as from_area, r.parent_id, r.appellation, 'label'::text as basis,
    null::text as source, ('The name "' || w.name || '" says it') as note
  from public.wines w join rules r on r.within_id = w.appellation_id
  where w.name ~* '\mgrand[[:space:]]+cru\M' and (r.vineyard_re is null or w.name ~* r.vineyard_re)
  order by w.id, r.vlen desc
), by_source (wine_id, from_area, parent_id, appellation, source, note) as (values
  ('42c48a45-141b-54de-8e82-cf6718a27e70'::uuid, 'e14c4e18-f9a6-5f93-9b7b-1f1acb6399f6'::uuid, 'd6a6d252-a5f0-586c-85d7-a45cdab4974f'::uuid, 'Saint-Émilion Grand Cru', 'https://www.inao.gouv.fr/en/saint-emilion-grand-cru-classement-next-decade', 'In the 2022 Saint-Émilion classification (approved by INAO on 8 September 2022), which is open only to wines of the AOC Saint-Émilion Grand Cru: Premier Grand Cru Classé B.'),
  ('7d3825c1-189c-47fb-a875-1ddf70645987'::uuid, 'e14c4e18-f9a6-5f93-9b7b-1f1acb6399f6'::uuid, 'd6a6d252-a5f0-586c-85d7-a45cdab4974f'::uuid, 'Saint-Émilion Grand Cru', 'https://www.inao.gouv.fr/en/saint-emilion-grand-cru-classement-next-decade', 'In the 2022 Saint-Émilion classification (approved by INAO on 8 September 2022), which is open only to wines of the AOC Saint-Émilion Grand Cru: Premier Grand Cru Classé A.'),
  ('5cce2426-1019-43ca-a485-cfd9f5b8174e'::uuid, 'e14c4e18-f9a6-5f93-9b7b-1f1acb6399f6'::uuid, 'd6a6d252-a5f0-586c-85d7-a45cdab4974f'::uuid, 'Saint-Émilion Grand Cru', 'https://www.inao.gouv.fr/en/saint-emilion-grand-cru-classement-next-decade', 'In the 2022 Saint-Émilion classification (approved by INAO on 8 September 2022), which is open only to wines of the AOC Saint-Émilion Grand Cru: Château Beauséjour (Héritiers Duffau-Lagarrosse), Premier Grand Cru Classé B.'),
  ('123e15f9-7cde-4738-ab30-ce5077ec1298'::uuid, 'e14c4e18-f9a6-5f93-9b7b-1f1acb6399f6'::uuid, 'd6a6d252-a5f0-586c-85d7-a45cdab4974f'::uuid, 'Saint-Émilion Grand Cru', 'https://www.ventealapropriete.com/en/vente/ficheproduitprint/PR21453', 'The second wine of Château Pavie, sold as "Arômes de Pavie - Saint-Emilion Grand Cru".'),
  ('0dc2705c-8f05-4f66-bfab-33c5c07ef6e9'::uuid, 'd5d4adf2-337f-4ece-8d8c-b83e9d04b118'::uuid, '9659f515-5048-51bd-bd4f-5a424dbd9b89'::uuid, 'Alsace Grand Cru Pfingstberg', 'https://www.jancisrobinson.com/tastings/234269', 'Reviewed as "Valentin Zusslin, Pfingstberg Riesling 2017, Alsace Grand Cru"; Decanter lists it as Riesling Grand Cru Pfingstberg.'),
  ('44c877a0-1a00-42c1-8563-3f568a64cc1d'::uuid, 'd5d4adf2-337f-4ece-8d8c-b83e9d04b118'::uuid, '9659f515-5048-51bd-bd4f-5a424dbd9b89'::uuid, 'Alsace Grand Cru Mambourg', 'https://www.internationalfinewines.com.au/products/weinbach-alsace-grand-cru-mambourg-la-butte-du-calvaire-riesling-2023-1500ml', 'Sold as "Weinbach Alsace Grand Cru Mambourg La Butte du Calvaire Riesling"; a Riesling parcel in the Mambourg grand cru.')
)
select * from by_words
union all
select s.wine_id, s.from_area, s.parent_id, s.appellation, 'source', s.source, s.note from by_source s
where s.wine_id is not null and not exists (select 1 from by_words b where b.wine_id = s.wine_id);

-- The places, made once (an existing appellation of that name anywhere in France's tree is reused).
insert into public.geo_areas (id, name, level, parent_id, classification, status)
select gen_random_uuid(), m.appellation, 'appellation', m.parent_id, 'AOC', 'verified'
from (select distinct appellation, parent_id from rank_moves) m
where not exists (select 1 from public.geo_areas g where g.level = 'appellation' and lower(g.name) = lower(m.appellation));

-- The moves, logged first; a wine already moved (or moved by hand since) is left alone.
with target as (
  select m.*, (select g.id from public.geo_areas g where g.level = 'appellation' and lower(g.name) = lower(m.appellation) limit 1) as to_area
  from rank_moves m
), logged as (
  insert into public.rank_appellation_moves (wine_id, from_area, to_area, appellation, basis, source, note)
  select t.wine_id, t.from_area, t.to_area, t.appellation, t.basis, t.source, t.note from target t
  join public.wines w on w.id = t.wine_id and w.appellation_id = t.from_area
  on conflict (wine_id) do nothing
  returning wine_id, to_area, from_area
)
update public.wines w set appellation_id = l.to_area from logged l where w.id = l.wine_id and w.appellation_id = l.from_area;

commit;

-- Check: what moved, and why.
select m.appellation, m.basis, count(*) as wines from public.rank_appellation_moves m group by 1, 2 order by 1, 2;
select p.name as producer, w.name as wine, m.appellation, m.basis, coalesce(m.source, m.note) as why
from public.rank_appellation_moves m join public.wines w on w.id = m.wine_id left join public.producers p on p.id = w.producer_id order by 3, 1;

